t.script:
(function() {
    var selectedProviderId = null;
    var selectedProviderCode = '';
    var providerRadios = document.querySelectorAll('input[name="payment_provider"]');
    var payBtn = document.getElementById('logspace-pay-btn');
    var paySpinner = document.getElementById('pay-spinner');
    var payBtnText = document.getElementById('pay-btn-text');

    // Build provider code map
    var providerCodeMap = {};

    providerCodeMap[] = '';


    // First available payment method ID
    var paymentMethodId = 0;


        if (!paymentMethodId) paymentMethodId = ;



    // JSON-RPC helper using fetch
    function jsonRpc(route, params) {
        return fetch(route, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': odoo.csrf_token || '',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: params,
                id: Math.floor(Math.random() * 1000000),
            }),
        }).then(function(response) {
            return response.json();
        }).then(function(data) {
            if (data.error) throw new Error(data.error.message || 'RPC Error');
            return data.result;
        });
    }

    // Provider selection: show corresponding inline form
    providerRadios.forEach(function(radio) {
        radio.addEventListener('change', function() {
            selectedProviderId = parseInt(this.value);
            selectedProviderCode = providerCodeMap[selectedProviderId] || '';
            payBtn.disabled = false;

            // Highlight selected provider radio
            document.querySelectorAll('.logspace-provider-option').forEach(function(opt) {
                opt.classList.remove('border-primary', 'bg-light');
            });
            this.closest('.logspace-provider-option').classList.add('border-primary', 'bg-light');

            // Hide all inline forms, then show the selected one
            document.querySelectorAll('.logspace-provider-inline-form').forEach(function(form) {
                form.classList.add('d-none');
            });
            var selectedForm = document.getElementById('inline_form_' + selectedProviderId);
            if (selectedForm) {
                selectedForm.classList.remove('d-none');
            }
        });
    });

    // Pay button click
    if (payBtn) {
        payBtn.addEventListener('click', function() {
            if (!selectedProviderId) return;

            // Show spinner
            payBtn.disabled = true;
            paySpinner.classList.remove('d-none');
            payBtnText.textContent = 'Processing...';

            jsonRpc('/logspace/booking/payment/transaction', {
                provider_id: selectedProviderId,
                payment_method_id: paymentMethodId,
            }).then(function(processingValues) {
                if (processingValues.error) {
                    alert('Error: ' + processingValues.error);
                    resetButton();
                    return;
                }

                if (processingValues.state === 'error') {
                    alert('Payment error: ' + (processingValues.state_message || 'Unknown error'));
                    resetButton();
                    return;
                }

                // Redirect flow: inject and auto-submit the redirect form (e.g., wire transfer)
                if (processingValues.redirect_form_html) {
                    var div = document.createElement('div');
                    div.innerHTML = processingValues.redirect_form_html;
                    var redirectForm = div.querySelector('form');
                    if (redirectForm) {
                        redirectForm.setAttribute('id', 'o_payment_redirect_form');
                        redirectForm.setAttribute('target', '_top');
                        document.body.appendChild(redirectForm);
                        redirectForm.submit();
                        return;
                    }
                }

                // Direct flow (e.g., demo provider): simulate payment then redirect
                if (processingValues.provider_code === 'demo') {
                    jsonRpc('/payment/demo/simulate_payment', {
                        reference: processingValues.reference,
                        payment_details: 'demo',
                        simulated_state: 'done',
                    }).then(function() {
                        // Keep spinner visible for 3s so user sees processing state
                        setTimeout(function() {
                            window.location = '/payment/status';
                        }, 3000);
                    }).catch(function() {
                        window.location = '/payment/status';
                    });
                    return;
                }

                // Fallback: redirect to status page
                window.location = '/payment/status';
            }).catch(function(error) {
                console.error('Payment error:', error);
                alert('Payment processing failed. Please try again.');
                resetButton();
            });
        });
    }

    function resetButton() {
        payBtn.disabled = false;
        paySpinner.classList.add('d-none');
        payBtnText.innerHTML = 'Pay ';
    }
})();
